contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depAmt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depAmt)); require(depAmt <= 1000000000000000000000000000000);
        require(address(this).balance >= depAmt);
        c.deposit{value: depAmt}(); if (__ESBMC_reverted()) return;
        uint cBalBefore = address(c).balance;
        uint balBefore = address(this).balance;
        uint creditAfterDeposit = depAmt;
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(cBalBefore >= creditAfterDeposit ? (!reverted && address(this).balance == balBefore + creditAfterDeposit && address(c).balance == cBalBefore - creditAfterDeposit) : (reverted && address(this).balance == balBefore && address(c).balance == cBalBefore));
    }

    receive() external payable {}
}

