// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 depAmt) internal {
        depAmt = bound(depAmt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depAmt);
        try c.deposit{value: depAmt}() {} catch { return; }
        uint cBalBefore = address(c).balance;
        uint balBefore = address(this).balance;
        uint creditAfterDeposit = depAmt;
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(cBalBefore >= creditAfterDeposit ? (!reverted && address(this).balance == balBefore + creditAfterDeposit && address(c).balance == cBalBefore - creditAfterDeposit) : (reverted && address(this).balance == balBefore && address(c).balance == cBalBefore));
    }

    function testFuzz_run(uint256 depAmt) public {
        _run(depAmt);
    }

    receive() external payable {}
}
